    99	// The point of the exercise: the sorted sequence's last first-component is
   100	// MaxFirst of the INPUT. Before prelude.dfy had SortIsSorted and SortLastIsMax
   101	// this could not be stated at all, because nothing said Sort produced an
   102	// ordered sequence -- only that it was a permutation.
   103	//
   104	// `less` is a parameter rather than a named constant on purpose: a ghost
   105	// function returning a lambda gives Dafny a value it will not identify with
   106	// the same lambda written at the call site, and every fact about Sort then
   107	// fails to transfer.
   108	lemma LastIsMaxFirst(pairs: seq<(int, int)>, less: ((int, int), (int, int)) -> bool)
   109	  requires |pairs| > 0
   110	  requires StrictTotalOrder(less)
   111	  requires forall a: (int, int), b: (int, int) :: !less(a, b) ==> b.0 <= a.0
   112	  ensures |Sort(pairs, less)| == |pairs|
   113	  ensures Sort(pairs, less)[|pairs| - 1].0 == MaxFirst(pairs)
   114	{
   115	  var d := Sort(pairs, less);
   116	  SortLastIsMax(pairs, less);
   117	  SortKeepsElems(pairs, less);
   118	  MaxFirstBounds(pairs);
   119	  MaxFirstAttained(pairs);
   120	
   121	  assert d[|d| - 1] in d;
   122	  assert d[|d| - 1] in pairs;              // SortKeepsElems
   123	  assert d[|d| - 1].0 <= MaxFirst(pairs);  // MaxFirstBounds
   124	
   125	  var w :| w in pairs && w.0 == MaxFirst(pairs);
   126	  assert !less(d[|d| - 1], w);             // SortLastIsMax
   127	  assert w.0 <= d[|d| - 1].0;              // the refinement hypothesis
   128	}
