   130	lemma MaxFirstAttained(s: seq<(int, int)>)
   131	  requires |s| > 0
   132	  ensures exists w :: w in s && w.0 == MaxFirst(s)
   133	  decreases |s|
   134	{
   135	  if |s| == 1 { assert s[0] in s && s[0].0 == MaxFirst(s); }
   136	  else {
   137	    MaxFirstAttained(s[1..]);
   138	    var m := MaxFirst(s[1..]);
   139	    if s[0].0 > m { assert s[0] in s && s[0].0 == MaxFirst(s); }
   140	    else {
   141	      var w :| w in s[1..] && w.0 == m;
   142	      assert w in s;
   143	    }
   144	  }
   145	}
