   168	  var d := Sort(pairs, (x: (int, int), y: (int, int)) => x.0 < y.0 || (x.0 == y.0 && x.1 < y.1));
   169	  assert d == Sort(pairs, less);
   170	  steps := 1 + SortCost(|pairs|);
