   195	    nex := 0;
   196	    var p := k;
   197	    while idx < n && d[idx].0 < i
   198	      invariant 0 <= idx <= n
   199	      invariant steps <= base + 12 * i + 2 * idx
   200	      decreases n - idx
   201	    {
   202	      idx := idx + 1;
   203	      steps := steps + 2;
   204	    }
   205	    while idx < n && d[idx].0 == i
   206	      invariant 0 <= idx <= n
   207	      invariant steps <= base + 12 * i + 2 * idx
   208	      decreases n - idx
   209	    {
   210	      nex := nex + d[idx].1;
   211	      idx := idx + 1;
   212	      steps := steps + 2;
   213	    }
