    36	// SplitCharFrom consumes one character of s per recursive call, so the number
    37	// of pieces it can produce is bounded by the number of characters left plus
    38	// the one piece already carried in acc.
    39	lemma SplitCharFromCount(s: string, sep: char, i: int, cur: string, acc: seq<string>)
    40	  requires 0 <= i <= |s|
    41	  ensures |SplitCharFrom(s, sep, i, cur, acc)| <= |acc| + (|s| - i) + 1
    42	  decreases |s| - i
    43	{
    44	  if i < |s| {
    45	    if s[i] == sep {
    46	      SplitCharFromCount(s, sep, i + 1, "", acc + [cur]);
    47	    } else {
    48	      SplitCharFromCount(s, sep, i + 1, cur + [s[i]], acc);
    49	    }
    50	  }
    51	}
