    62	  steps := 1;
    63	  var a := k;
    64	  var b := m;
    65	  var pieces := SplitChar(s, '*');
    66	  steps := steps + (|s| + 1);
    67	  SplitCharCount(s, '*');
    68	  var lens := seq(|pieces|, idx requires 0 <= idx < |pieces| => |pieces[idx]|);
    69	  steps := steps + |pieces|;
    70	  var row := Sort(lens, LessInt);
    71	  steps := steps + SortCost(|lens|);
    72	  SortCostWithin(|lens|, |s| + 1);
    73	  assert |row| <= |s| + 1;
    74	  var total := 0;
    75	  var i := 0;
    76	  while i < |row|
    77	    invariant 0 <= i <= |row|
    78	    invariant steps <= 2 * NLogN(|s| + 1) + 6 * |s| + 10 + 6 * i
    79	    decreases |row| - i
    80	  {
